const $=s=>document.querySelector(s);const menu=$('.menu'),nav=$('nav');
menu?.addEventListener('click',()=>{let open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);nav.classList.toggle('open',open)});
function closeMenu(){nav?.classList.remove('open');menu?.setAttribute('aria-expanded','false');menu?.focus()}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('open'))closeMenu()});nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{if(nav.classList.contains('open'))closeMenu()}));
const c=window.FSEL_CONTENT;let rec,stream,chunks=[],url,timer,startTime,generation=0;let active=true;
function state(t){if($('#mic-state'))$('#mic-state').textContent=t}
function stopTracks(){stream?.getTracks().forEach(t=>t.stop());stream=null;clearInterval(timer)}
function dispose(){generation++;if(rec?.state==='recording'){rec.onstop=null;rec.stop()}stopTracks();if(url)URL.revokeObjectURL(url);url=null;const a=$('#playback');if(a){a.pause();a.removeAttribute('src');a.hidden=true}if($('#record')){$('#record').hidden=false;$('#stop').hidden=true;$('#delete').hidden=true;$('#retry').hidden=true;$('#record').disabled=false;$('#timer').textContent='00:00'}chunks=[]}
window.addEventListener('pagehide',()=>{active=false;dispose()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&rec?.state==='recording')stopRecording()});
async function record(){dispose();const token=generation;if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){state('Thiết bị hoặc trình duyệt chưa hỗ trợ ghi âm. Bạn vẫn có thể khám phá bài mẫu.');return}state('Đang xin quyền truy cập microphone…');$('#record').disabled=true;try{let s=await navigator.mediaDevices.getUserMedia({audio:true});if(token!==generation||!active){s.getTracks().forEach(t=>t.stop());return}stream=s;rec=new MediaRecorder(stream);chunks=[];rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};rec.onstop=()=>{if(token!==generation)return;stopTracks();url=URL.createObjectURL(new Blob(chunks,{type:rec.mimeType}));$('#playback').src=url;$('#playback').hidden=false;$('#delete').hidden=false;$('#retry').hidden=false;$('#stop').hidden=true;$('#record').hidden=true;state('Đã ghi xong. Nhấn phát để nghe lại.');};rec.start();startTime=Date.now();$('#record').hidden=true;$('#stop').hidden=false;state('Đang ghi âm');timer=setInterval(()=>{let s=Math.floor((Date.now()-startTime)/1000);$('#timer').textContent=String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');if(s>=180)stopRecording()},250)}catch(e){stopTracks();$('#record').disabled=false;state(e.name==='NotAllowedError'?'Quyền microphone bị từ chối. Cho phép microphone trong trình duyệt rồi thử lại.':e.name==='NotFoundError'?'Không tìm thấy microphone. Kết nối thiết bị rồi thử lại.':'Không thể mở microphone. Hãy thử lại.')}}
function stopRecording(){if(rec?.state==='recording')rec.stop();stopTracks()}
if(c){
 const scenes={video:['assets/lesson-screen.png','Giao diện Video Lesson FSEL'],forum:['assets/speaking-screen.png','Giao diện Speaking từ thiết kế FSEL'],practice:['assets/reading-screen.png','Giao diện bài tập Reading FSEL']};
 document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-scene]').forEach(x=>x.classList.toggle('active',x===b));$('#journey-image').src=scenes[b.dataset.scene][0];$('#journey-image').alt=scenes[b.dataset.scene][1]});
 function tab(name){dispose();state('Sẵn sàng thu âm');$('#lesson-video').pause();for(const n of ['video','speaking']){$('#tab-'+n).setAttribute('aria-selected',n===name);$('#tab-'+n).tabIndex=n===name?0:-1;$('#'+n+'-demo').hidden=n!==name}}
 for(const n of ['video','speaking']){$('#tab-'+n).onclick=()=>tab(n);$('#tab-'+n).onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();let other=n==='video'?'speaking':'video';tab(other);$('#tab-'+other).focus()}}}
 $('#speaking-prompt').textContent=c.speaking.prompt;$('#speaking-instruction').textContent='Nói về quê hương hoặc ngôi làng của bạn.';$('#sample-text').textContent='“'+c.speaking.sample+'”';$('#sample-note').textContent='Bản chép lời mẫu trong thiết kế FSEL.';
 c.speaking.feedback.forEach(([title,body])=>{let d=document.createElement('details'),s=document.createElement('summary'),p=document.createElement('p');s.textContent=title;p.textContent=body;d.append(s,p);$('#feedback-content').append(d)});
 $('#feedback-content').insertAdjacentHTML('beforeend','<p class="caption">Phản hồi mẫu trích từ thiết kế, dùng để khám phá cách đọc nhận xét. Không phải đánh giá bản ghi của bạn.</p>');
 function mode(recording){dispose();$('#record-panel').hidden=!recording;$('#sample-panel').hidden=recording;$('#sample-feedback').hidden=recording;$('#record-help').hidden=!recording;$('#record-mode').setAttribute('aria-pressed',recording);$('#sample-mode').setAttribute('aria-pressed',!recording);state('Sẵn sàng thu âm')}
 $('#record-mode').onclick=()=>mode(true);$('#sample-mode').onclick=()=>mode(false);$('#record').onclick=record;$('#retry').onclick=record;$('#stop').onclick=stopRecording;$('#delete').onclick=()=>{dispose();state('Đã xóa bản ghi. Bạn có thể thu lại.')};$('#playback').onplay=()=>state('Đang phát lại');$('#playback').onended=()=>state('Đã phát xong. Bạn có thể nghe lại hoặc thu lại.');$('#playback').onpause=()=>{if(!$('#playback').ended)state('Đã tạm dừng phát lại')};
 const video=$('#lesson-video');let answered=false;
 function question(){if(!c.question)return;video.pause();$('#question').hidden=false;$('#question-text').textContent=c.question.text;$('#answers').replaceChildren();c.question.answers.forEach((t,i)=>{let b=document.createElement('button');b.textContent=t;b.onclick=()=>{answered=true;b.classList.add(i===c.question.correct?'correct':'wrong');$('#explanation').hidden=false;$('#explanation').textContent=(i===c.question.correct?'Chính xác. ':'Chưa chính xác. ')+c.question.explanation;$('#video-next').hidden=false;$('#answers').querySelectorAll('button').forEach(x=>x.disabled=true);$('#video-state').textContent=i===c.question.correct?'Đáp án đúng':'Đáp án chưa đúng'};$('#answers').append(b)})}
 $('#video-start').onclick=()=>{if(!c.video){$('#video-state').textContent='Chưa tải được video bài học. Bạn có thể thử hoạt động Luyện nói.';$('#video-start').textContent='Thử lại';$('#video-reset').hidden=false;return}video.src=c.video;video.hidden=false;$('#video-poster').hidden=true;video.play().catch(()=>$('#video-state').textContent='Không thể phát video. Hãy thử lại.')};video.ontimeupdate=()=>{if(c.question&&!answered&&video.currentTime>=c.question.time)question()};video.onplay=()=>$('#video-state').textContent='Đang phát';video.onerror=()=>{$('#video-state').textContent='Không tải được video. Hãy thử lại.';$('#video-start').hidden=false};video.onended=()=>{$('#video-state').textContent='Hoàn thành hoạt động';$('#video-reset').hidden=false};$('#video-next').onclick=()=>{$('#question').hidden=true;$('#video-next').hidden=true;video.play()};$('#video-reset').onclick=()=>{video.pause();video.currentTime=0;answered=false;$('#question').hidden=true;$('#explanation').hidden=true;$('#video-next').hidden=true;$('#video-state').textContent='Sẵn sàng khám phá bài học';$('#video-start').textContent='Khám phá bài học'};
}
$('#campus-form')?.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);const body=`Tên: ${d.get('name')}\nTrường: ${d.get('school')}\nEmail: ${d.get('email')}\nNhu cầu: ${d.get('need')}`;$('#form-state').textContent='Đã chuẩn bị nội dung email. Vui lòng gửi trong ứng dụng email của bạn; yêu cầu chưa được xác nhận tiếp nhận.';location.href='mailto:support_fsel@atlantic.edu.vn?subject='+encodeURIComponent('Trao đổi triển khai FSEL Campus')+'&body='+encodeURIComponent(body)});

document.querySelectorAll('img.product').forEach(img=>{const a=document.createElement('a');a.href=img.src;a.target='_blank';a.rel='noopener';a.setAttribute('aria-label','Xem ảnh giao diện ở kích thước đầy đủ');img.replaceWith(a);a.append(img)});
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.animate([{opacity:.5,transform:'translateY(18px)'},{opacity:1,transform:'translateY(0)'}],{duration:600,easing:'ease-out'});observer.unobserve(e.target)}})},{threshold:.12});if(!matchMedia('(prefers-reduced-motion: reduce)').matches)document.querySelectorAll('section h2,section p,section .product').forEach(el=>observer.observe(el))}
